using FamilyVeda.Application.Common;
using FamilyVeda.Application.Portal;
using FamilyVeda.Domain.Clinical;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Portal;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.UnitTests;

public sealed class AppointmentServiceTests
{
    private static AppDbContext NewDb() =>
        new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);

    private sealed record Fixture(AppDbContext Db, UserAccount Head, UserAccount OtherAdultUser, Member HeadMember, Member OtherAdultMember, Member MinorMember, Doctor Doctor, Family Family);

    private static async Task<Fixture> SeedAsync(AppDbContext db)
    {
        var head = new UserAccount { Email = "head@example.invalid", PasswordHash = "x", DisplayName = "Head", UserType = UserType.FamilyUser };
        var otherAdultUser = new UserAccount { Email = "other@example.invalid", PasswordHash = "x", DisplayName = "Other Adult", UserType = UserType.FamilyUser };
        var family = new Family { Name = "F", CreatedByUser = head, FamilyCode = "FV-CCC333" };
        var headMember = new Member { Family = family, User = head, DisplayName = "Head", DateOfBirth = new DateOnly(1980, 1, 1), Role = FamilyRole.Head };
        var otherAdultMember = new Member { Family = family, User = otherAdultUser, DisplayName = "Other Adult", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.AdultMember };
        var minorMember = new Member { Family = family, DisplayName = "Minor", DateOfBirth = DateOnly.FromDateTime(DateTime.UtcNow).AddYears(-10), Role = FamilyRole.MinorMember };
        var doctorUser = new UserAccount { Email = "doc@example.invalid", PasswordHash = "x", DisplayName = "Doc", UserType = UserType.Doctor };
        var doctor = new Doctor { User = doctorUser, RegistrationNumberHash = "h", RegistrationNumberLastFour = "1234", VerificationStatus = VerificationStatus.Verified };
        var assignment = new FamilyDoctorAssignment { Family = family, Doctor = doctor, IsPrimary = true };
        db.AddRange(head, otherAdultUser, family, headMember, otherAdultMember, minorMember, doctorUser, doctor, assignment);
        await db.SaveChangesAsync();
        return new Fixture(db, head, otherAdultUser, headMember, otherAdultMember, minorMember, doctor, family);
    }

    [Fact]
    public async Task Book_AdultForAnotherAdult_Returns404()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var service = new AppointmentService(db, new StubCurrentUser(f.OtherAdultUser.Id));
        // A second adult account trying to book for the head's other-adult member id (not itself)
        var thirdAdultUser = new UserAccount { Email = "third@example.invalid", PasswordHash = "x", DisplayName = "Third", UserType = UserType.FamilyUser };
        db.Add(thirdAdultUser);
        await db.SaveChangesAsync();
        var thirdService = new AppointmentService(db, new StubCurrentUser(thirdAdultUser.Id));

        var act = () => thirdService.BookAsync(new CreateAppointmentRequest(f.OtherAdultMember.Id, DateTimeOffset.UtcNow.AddDays(1), 30, "Checkup"), CancellationToken.None);

        await act.Should().ThrowAsync<NotFoundException>();
    }

    [Fact]
    public async Task Book_HeadForMinor_Succeeds()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var service = new AppointmentService(db, new StubCurrentUser(f.Head.Id));

        var result = await service.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, DateTimeOffset.UtcNow.AddDays(1), 30, "Checkup"), CancellationToken.None);

        result.MemberId.Should().Be(f.MinorMember.Id);
        result.Status.Should().Be(AppointmentStatus.Requested);
    }

    [Fact]
    public async Task Book_OverlappingSlotForSameDoctor_Returns409()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var service = new AppointmentService(db, new StubCurrentUser(f.Head.Id));
        var start = DateTimeOffset.UtcNow.AddDays(1);
        await service.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, start, 30, "Checkup"), CancellationToken.None);

        var act = () => service.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, start.AddMinutes(15), 30, "Follow up"), CancellationToken.None);

        await act.Should().ThrowAsync<ConflictException>();
    }

    [Fact]
    public async Task Book_PastTime_IsRejected()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var service = new AppointmentService(db, new StubCurrentUser(f.Head.Id));

        var act = () => service.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, DateTimeOffset.UtcNow.AddDays(-1), 30, "Checkup"), CancellationToken.None);

        await act.Should().ThrowAsync<FamilyVeda.Application.Common.ValidationException>();
    }

    [Fact]
    public async Task GetMine_ForHead_NeverContainsOtherAdultsAppointments()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var otherAdultService = new AppointmentService(db, new StubCurrentUser(f.OtherAdultUser.Id));
        await otherAdultService.BookAsync(new CreateAppointmentRequest(f.OtherAdultMember.Id, DateTimeOffset.UtcNow.AddDays(1), 30, "Private visit"), CancellationToken.None);
        var headService = new AppointmentService(db, new StubCurrentUser(f.Head.Id));
        await headService.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, DateTimeOffset.UtcNow.AddDays(2), 30, "Minor visit"), CancellationToken.None);

        var mine = await headService.GetMineAsync(CancellationToken.None);

        mine.Should().OnlyContain(x => x.MemberId != f.OtherAdultMember.Id);
        mine.Should().Contain(x => x.MemberId == f.MinorMember.Id);
    }

    [Fact]
    public async Task DoctorTransition_InvalidStatus_Returns409()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var service = new AppointmentService(db, new StubCurrentUser(f.Head.Id));
        var appointment = await service.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, DateTimeOffset.UtcNow.AddDays(1), 30, "Checkup"), CancellationToken.None);
        var doctorUserId = f.Doctor.UserId;
        var doctorService = new AppointmentService(db, new StubCurrentUser(doctorUserId, UserType.Doctor));

        // Requested -> Completed is invalid (must go through Confirmed first)
        var act = () => doctorService.CompleteAsync(appointment.Id, new AppointmentActionRequest(null), CancellationToken.None);

        await act.Should().ThrowAsync<ConflictException>();
    }

    [Fact]
    public async Task GetForDoctor_MapsEveryAppointmentWithMemberFamilyAndDoctor()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var headService = new AppointmentService(db, new StubCurrentUser(f.Head.Id));
        var later = await headService.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, DateTimeOffset.UtcNow.AddDays(2), 30, "Minor visit"), CancellationToken.None);
        var sooner = await headService.BookAsync(new CreateAppointmentRequest(f.HeadMember.Id, DateTimeOffset.UtcNow.AddDays(1), 30, "Head visit"), CancellationToken.None);
        var doctorService = new AppointmentService(db, new StubCurrentUser(f.Doctor.UserId, UserType.Doctor));

        var list = await doctorService.GetForDoctorAsync(null, null, CancellationToken.None);

        list.Select(x => x.Id).Should().Equal(sooner.Id, later.Id);
        list.Select(x => x.MemberDisplayName).Should().Equal("Head", "Minor");
        list.Should().OnlyContain(x => x.FamilyName == "F" && x.Doctor.Id == f.Doctor.Id && x.Doctor.DisplayName == "Doc");
    }

    [Fact]
    public async Task GetForDoctor_NeverReturnsAnotherDoctorsAppointments()
    {
        await using var db = NewDb();
        var f = await SeedAsync(db);
        var headService = new AppointmentService(db, new StubCurrentUser(f.Head.Id));
        await headService.BookAsync(new CreateAppointmentRequest(f.MinorMember.Id, DateTimeOffset.UtcNow.AddDays(1), 30, "Minor visit"), CancellationToken.None);
        var otherDoctorUser = new UserAccount { Email = "doc2@example.invalid", PasswordHash = "x", DisplayName = "Doc Two", UserType = UserType.Doctor };
        var otherDoctor = new Doctor { User = otherDoctorUser, RegistrationNumberHash = "h2", RegistrationNumberLastFour = "5678", VerificationStatus = VerificationStatus.Verified };
        db.AddRange(otherDoctorUser, otherDoctor);
        await db.SaveChangesAsync();
        var otherDoctorService = new AppointmentService(db, new StubCurrentUser(otherDoctorUser.Id, UserType.Doctor));

        var list = await otherDoctorService.GetForDoctorAsync(null, null, CancellationToken.None);

        list.Should().BeEmpty();
    }

    private sealed class StubCurrentUser(Guid userId, UserType userType = UserType.FamilyUser) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => userType;
    }
}
